BEGIN IMMEDIATE;
UPDATE knowledge_nodes SET metadata_json='{"source": "fengze_politics_course_catalog", "classification_sources": ["D:/gong/teacher_fengze_politics/cleaned_transcripts/20250817 政治理论(时政)加课3.doc.txt"], "classification_role": "category", "practice_category": true, "classification_origin": "local_classification_review_20261014", "course_sources": [{"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 24520, "end_char": 24820, "line": 1, "excerpt": "是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 6304, "end_char": 6604, "line": 1, "excerpt": "神。啊，就这三个方面，其实你主要联系前面就行了，也就是开天辟地，对不对？敢为人先首创嘛，毕竟红船精神是我们党创建的时候啊，创建的时候。然后紧接着后面其他的啊，像井冈山精神这个不做重点介绍啊啊，井冈山呢呃，这个我们之前强调的是在一九二七年还记得吗啊，秋收起义结束之后啊，然后呢？呃秋收起义最终的这个结果不是失败了吗？失败之后，然后啊，毛泽东同志带领着我们当时的起义队伍转战到井冈山，是不是哎？然后成立了井冈山根据地啊。好，这个大家知道，井冈山是我们的第一个革命根据地，其实就行了啊，然后它里面的这些内容简单，看看这个不做一个重点啊。然后往下。第二个重点呢，就是它看到了吗？同学们叫遵义会议精神啊，遵义会", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 7667, "end_char": 7967, "line": 1, "excerpt": "全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 38335, "end_char": 38635, "line": 3, "excerpt": "命这一重大问题上认识更加清醒，行动更加坚定。因为我们之前说过自我革命，这是第几个答案，同学们。之前是不是讲了对吧？前面刚讲完啊，自我革命，这是我们党跳出治乱兴衰历史周期律的第二个答案，对吧？唉，前面说过就不再多说啊，所以你看我们坚持把它作为第二个答案。所以我们对于自我革命这个问题认识更加先行，更加坚定啊，那第二个就是我们在扎实开展党纪学习教育。啊，党纪学习教育那么全党同志遵守唉，遵规守纪的意识更加增强了啊，好，这是党纪，然后紧接着第三。持续加大反腐败力度，铲除腐败滋生的土壤和条件。同学们啊，这个反腐败力度大不大？你就看我们每天的新闻就行了，对吧？哎，每天你看，无论是我们的这个央央视新闻，还是新", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 18988, "end_char": 19288, "line": 1, "excerpt": "国企业，中国公民一样的这种待遇。那你来不来？对吧？唉，是要来的啊，那么往下第八个第八个呢？强调多边主义是解决世界面临困难挑战的必然选择，而经济全球化是不可阻挡的历史潮流。这个注意别。别让这两个词互换位置就行了啊，因为之前我们在强调世界经济发展的时候，一直在说经济全球化，它是一种潮流，对吧？哎，因为现在你看没有哪个国家真正的能够独立于现代经济全球化的。潮流之外啊，没有哪个国家能真正的独立，任何国家的发展对吧？你看或者说有一些，尤其是做这种进出口企业的，它更加依赖于这种经济的发展啊。啊，那么还有就是前面说的多边主义，它是解决世界面临困难挑战的必然选择。当有一些问题出现的时候，对吧？各个国家之间我们", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}' WHERE id='political_theory.policy.history';
